param([switch]$Aplicar)
$ErrorActionPreference = 'Stop'
$relative = 'src/modulos/auditoria/AuditoriaView.vue'
$target = Join-Path (Get-Location).Path $relative
if (!(Test-Path $target)) { throw "No existe $relative. Ejecuta en la raiz de LERABOT." }
Write-Host 'FASE 5 - AUDITORIA FINAL: filtros inmediatos, graficos compactos, tabla con scroll, modal JSON.'
Write-Host "Archivo: $relative"
Write-Host 'No llama a AWS ni ejecuta cambios backend.'
if (!$Aplicar) { Write-Host 'VISTA PREVIA. Ejecuta con -Aplicar'; exit 0 }
$backup = "$target.bak-$(Get-Date -Format yyyyMMdd-HHmmss)"
Copy-Item $target $backup
$data = ''
[System.IO.File]::WriteAllBytes($target, [Convert]::FromBase64String($data))
Write-Host "ACTUALIZADO: $relative"
Write-Host "Respaldo: $backup"
Write-Host 'Valida: npm run type-check; npm run build; npm run dev'
